import express from 'express';
import { Pool } from 'pg';
import zlib from 'zlib';
import { pipeline, Transform } from 'stream';
import { promisify } from 'util';

const pipelineAsync = promisify(pipeline);

const pool = new Pool({
  host: process.env.DB_HOST || 'localhost',
  port: 5432,
  database: 'analytics',
  user: process.env.DB_USER || 'app',
  password: process.env.DB_PASS || 'secret',
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 5000,
});

interface DecompressionPolicy {
  maxCompressedSize: number;
  maxRatio: number;
  windowSize: number;
}

const DEFAULT_POLICY: DecompressionPolicy = {
  maxCompressedSize: 10 * 1024 * 1024, // 10MB compressed
  maxRatio: 100,
  windowSize: 65536,
};

class SafeInflateTransform extends Transform {
  private compressedBytes: number = 0;
  private decompressedBytes: number = 0;
  private policy: DecompressionPolicy;
  private windowBuffer: Buffer[] = [];
  private windowTotal: number = 0;

  constructor(policy: DecompressionPolicy) {
    super();
    this.policy = policy;
  }

  _transform(chunk: Buffer, _encoding: string, callback: Function) {
    this.decompressedBytes += chunk.length;
    this.windowBuffer.push(chunk);
    this.windowTotal += chunk.length;

    // Sliding window ratio check
    while (this.windowTotal > this.policy.windowSize && this.windowBuffer.length > 1) {
      const removed = this.windowBuffer.shift()!;
      this.windowTotal -= removed.length;
    }

    // Check overall ratio against compressed input size
    if (this.compressedBytes > 0) {
      const currentRatio = this.decompressedBytes / this.compressedBytes;
      if (currentRatio > this.policy.maxRatio) {
        callback(new Error(`Decompression ratio ${currentRatio.toFixed(1)} exceeds limit ${this.policy.maxRatio}`));
        return;
      }
    }

    this.push(chunk);
    callback();
  }

  setCompressedSize(size: number) {
    this.compressedBytes = size;
  }
}

async function decompressPayload(compressedData: Buffer, policy: DecompressionPolicy): Promise<Buffer> {
  if (compressedData.length > policy.maxCompressedSize) {
    throw new Error(`Compressed size ${compressedData.length} exceeds limit ${policy.maxCompressedSize}`);
  }

  const safeTransform = new SafeInflateTransform(policy);
  safeTransform.setCompressedSize(compressedData.length);

  const chunks: Buffer[] = [];
  const collector = new Transform({
    transform(chunk, _enc, cb) {
      chunks.push(chunk);
      cb();
    }
  });

  const { Readable } = await import('stream');
  const inputStream = Readable.from(compressedData);
  const inflater = zlib.createInflate();

  await pipelineAsync(inputStream, inflater, safeTransform, collector);

  return Buffer.concat(chunks);
}

function computeEffectivePolicy(userTier: string, contentType: string): DecompressionPolicy {
  const base = { ...DEFAULT_POLICY };

  if (userTier === 'premium') {
    base.maxCompressedSize = 50 * 1024 * 1024;
    base.maxRatio = 500;
  } else if (userTier === 'enterprise') {
    base.maxCompressedSize = 100 * 1024 * 1024;
    base.maxRatio = 1000;
  }

  // Binary telemetry data is expected to have high compression ratios
  if (contentType === 'application/x-telemetry-bin') {
    base.maxRatio = base.maxRatio * 10;
  }

  return base;
}

const app = express();

app.use(express.raw({ limit: '100mb', type: '*/*' }));

app.post('/api/v2/ingest', async (req, res) => {
  const client = await pool.connect();
  try {
    const userTier = req.headers['x-user-tier'] as string || 'free';
    const contentType = req.headers['content-type'] as string || 'application/octet-stream';
    const encoding = req.headers['content-encoding'] as string;

    let payload: Buffer = req.body;

    if (encoding === 'deflate' || encoding === 'gzip') {
      const policy = computeEffectivePolicy(userTier, contentType);
      payload = await decompressPayload(req.body, policy);
    }

    await client.query('BEGIN');
    await client.query(
      'INSERT INTO raw_events (payload, received_at, tier) VALUES ($1, NOW(), $2)',
      [payload, userTier]
    );
    await client.query('COMMIT');

    res.status(201).json({ accepted: true, size: payload.length });
  } catch (err: any) {
    await client.query('ROLLBACK').catch(() => {});
    if (err.message?.includes('ratio') || err.message?.includes('size')) {
      res.status(413).json({ error: 'Payload too large or suspicious compression' });
    } else {
      res.status(500).json({ error: 'Internal error' });
    }
  } finally {
    client.release();
  }
});

app.listen(3000, () => console.log('Ingest service on :3000'));

export { app, decompressPayload, computeEffectivePolicy };
